// Standard iconography for Intelligent Commerce. Lucide is the single sanctioned
// icon set across all Stateset products — import icons from here (or directly from
// '@stateset/design/icons') rather than mixing libraries per app.
//
// Re-exporting the whole set keeps tree-shaking intact (named re-exports) while
// giving teams one import path and one version to standardize on.
export * from 'lucide-react';
export { icons as lucideIcons } from 'lucide-react';
